use std::{fs, panic, path::Path};
fn main() {
    panic::set_hook(Box::new(|_| {}));
    let path = Path::new("/work/tmp/summary-harness/justfile");
    let seeds = ["a := 'x'\nb:\n echo {{a}}\n", "f(x) := x\na := f('b')\n", "[arg('x', long)]\na x='a':\n", "set shell := ['sh', '-c']\na:\n", "x := f'foo{{\"x\"}}'\n", "a := if 'x' == 'y' { 'a' } else { 'b' }\n", "a := '''\n  x\n  y\n'''\n"];
    let alphabet = b"abcXYZ012 _-?@'\"`{}[]():=+/$\\\n\t\r,;!|&";
    let mut state = 0x531cafe_u64;
    for i in 0..200_000 {
        let mut next = || { state ^= state << 13; state ^= state >> 7; state ^= state << 17; state as usize };
        let mut data = seeds[next() % seeds.len()].as_bytes().to_vec();
        for _ in 0..1 + next() % 8 {
            let index = next() % (data.len() + 1);
            match next() % 3 {
                0 if index < data.len() => { data.remove(index); }
                1 if index < data.len() => data[index] = alphabet[next() % alphabet.len()],
                _ => data.insert(index, alphabet[next() % alphabet.len()]),
            }
        }
        let text = String::from_utf8(data).expect("ASCII mutations");
        fs::write(path, &text).expect("scratch file writable");
        if panic::catch_unwind(|| just::summary::summary(path)).is_err() {
            println!("PANIC iteration {i}: {text:?}");
            return;
        }
        if i % 50_000 == 0 { println!("checked {i}"); }
    }
    println!("200000 mutations: no caught panics");
}
